  7	/** An unsuccessful HTTP response, preserving its status for callers that need it. */
  8	export class HttpError extends Error {
  9	  constructor(
 10	    message: string,
 11	    readonly status: number,
 12	  ) {
 13	    super(message);
 14	    this.name = "HttpError";
 15	  }
 16	}
