 18	/** Builds request headers, adding a `Bearer` auth header when a token is present. */
 19	function buildHeaders(
 20	  clerkToken?: string | null,
 21	  contentTypeJson = false,
 22	  extraHeaders?: Record<string, string>,
 23	): Record<string, string> {
 24	  const headers: Record<string, string> = extraHeaders ? { ...extraHeaders } : {};
 25	  if (contentTypeJson) {
 26	    headers["Content-Type"] = "application/json";
 27	  }
 28	  if (clerkToken) {
 29	    headers["Authorization"] = `Bearer ${clerkToken}`;
 30	  }
 31	  return headers;
 32	}
 33	
 34	/**
 35	 * Core fetch scaffold shared by every helper below. Issues the request with the
 36	 * standard `credentials: "include"` and `buildHeaders(...)`, JSON-encoding a
 37	 * body when `withBody` is set (which also selects the JSON content-type header).
 38	 * Returns the raw `Response`; callers own any ok-check and body parsing.
 39	 */
 40	function sendRequest(
 41	  method: string,
 42	  path: string,
 43	  {
 44	    clerkToken,
 45	    jsonPayload,
 46	    withBody = false,
 47	    signal,
 48	    extraHeaders,
 49	  }: {
 50	    clerkToken?: string | null;
 51	    jsonPayload?: unknown;
 52	    withBody?: boolean;
 53	    signal?: AbortSignal;
 54	    extraHeaders?: Record<string, string>;
 55	  } = {},
 56	): Promise<Response> {
 57	  const init: RequestInit = {
 58	    method,
 59	    headers: buildHeaders(clerkToken, withBody, extraHeaders),
 60	    credentials: "include",
 61	  };
 62	  if (withBody) {
 63	    init.body = JSON.stringify(jsonPayload);
 64	  }
 65	  if (signal !== undefined) {
 66	    init.signal = signal;
 67	  }
 68	  return fetch(url(path), init);
 69	}
 70	
 71	/**
 72	 * Sends a JSON body via `method` and returns the parsed JSON response as `T`,
 73	 * throwing on a non-ok response (using the response text when present). A body
 74	 * is only parsed when the response is JSON, so endpoints that answer with an
 75	 * empty body (`Promise<void>` callers) are handled too. Shared by `postJson`
 76	 * and `patchJson`, which differ only in the HTTP method.
 77	 */
 78	async function requestWithJsonBody<T>(
 79	  method: string,
 80	  path: string,
 81	  payload: unknown,
 82	  clerkToken?: string | null,
 83	): Promise<T> {
 84	  const result = await sendRequest(method, path, {
 85	    clerkToken,
 86	    jsonPayload: payload,
 87	    withBody: true,
 88	  });
 89	
 90	  if (!result.ok) {
 91	    const text = await result.text().catch(() => "");
 92	    throw new Error(text || `Failed to ${method} ${path}`);
 93	  }
 94	
 95	  const contentType = result.headers.get("content-type");
 96	  if (contentType?.includes("application/json")) {
 97	    return (await result.json()) as T;
 98	  }
 99	  return undefined as T;
100	}
101	
102	export async function get<T>(
103	  path: string,
104	  clerkToken?: string | null,
105	  signal?: AbortSignal,
106	  extraHeaders?: Record<string, string>,
107	) {
108	  const result = await sendRequest("GET", path, { clerkToken, signal, extraHeaders });
109	
110	  if (result.ok) {
111	    const json = await result.json();
112	    return json as T;
113	  }
114	  throw new HttpError(`Failed to GET ${path}`, result.status);
115	}
