117	// eslint-disable-next-line @typescript-eslint/no-explicit-any
118	export async function post(path: string, payload: any, clerkToken?: string | null) {
119	  return sendRequest("POST", path, { clerkToken, jsonPayload: payload, withBody: true });
120	}
