122	/**
123	 * POSTs a JSON body and returns the parsed JSON response as `T`, throwing on a
124	 * non-ok response (using the response text when present). Mirrors `patchJson`:
125	 * a body is only parsed when the response is JSON, so endpoints that answer a
126	 * successful POST with an empty body (`Promise<void>` callers) are handled too.
127	 * Use this instead of the low-level `post` whenever the caller just needs the
128	 * parsed body; reach for `post` only when the raw `Response` is genuinely needed.
129	 */
130	// eslint-disable-next-line @typescript-eslint/no-explicit-any
131	export async function postJson<T>(
132	  path: string,
133	  payload: any,
134	  clerkToken?: string | null,
135	): Promise<T> {
136	  return requestWithJsonBody<T>("POST", path, payload, clerkToken);
137	}
