22	/**
23	 * Classify a failed share-view fetch so the recipient page can tell "this
24	 * link is the problem" from "the service could not answer".
25	 *
26	 * Permanent: the backend answered that the token is missing, unknown,
27	 * revoked, expired, or malformed (404 / 410 / other 4xx except 408/429).
28	 * Transient: 5xx, 408, 429, a network failure, or any error without a
29	 * status — including the mid-deploy connection-refused window. Ambiguous
30	 * failures are transient: better to ask a valid-link holder to retry than
31	 * to tell them the link is broken.
32	 */
33	export function classifyShareLoadFailure(error: unknown): ShareLoadFailureKind {
34	  if (error instanceof HttpError) {
35	    if (TRANSIENT_CLIENT_STATUSES.has(error.status)) {
36	      return "transient";
37	    }
38	    if (error.status >= 400 && error.status < 500) {
39	      return "permanent";
40	    }
41	    return "transient";
42	  }
